<template><div class="max-w-3xl mx-auto p-5 sm:p-8" v-if="server"><h1 class="text-2xl font-bold text-white">ตั้งค่าเซิร์ฟเวอร์</h1><p class="text-dark-400 text-sm mt-1">{{ editable ? 'บันทึกแล้วค่าใหม่จะถูกใช้ตอนเริ่มครั้งถัดไป' : 'ต้องหยุดเซิร์ฟเวอร์ก่อนจึงแก้ไขการตั้งค่าได้' }}</p><form class="mt-6 space-y-5" @submit.prevent="save"><fieldset :disabled="!editable" class="space-y-5 disabled:opacity-50"><section class="panel"><h2>รายละเอียด</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field sm:col-span-2">ชื่อ<input v-model="form.name" required /></label><label class="field">พอร์ต<input v-model.number="form.port" type="number" min="1" max="65535" /></label><label class="field">Memory (MB)<input v-model.number="form.memory_mb" type="number" min="256" /></label><label class="field">ผู้เล่นสูงสุด<input v-model.number="form.max_players" type="number" min="1" /></label><label class="field">MOTD<input v-model="form.motd" /></label></div></section><section class="panel"><h2>เกมเพลย์</h2><div class="grid sm:grid-cols-2 gap-4 mt-4"><label class="field">โหมดเกม<select v-model="form.gamemode"><option v-for="v in ['survival','creative','adventure','spectator']" :key="v">{{v}}</option></select></label><label class="field">ความยาก<select v-model="form.difficulty"><option v-for="v in ['peaceful','easy','normal','hard']" :key="v">{{v}}</option></select></label><label class="check"><input v-model="form.online_mode" type="checkbox" /> ตรวจสอบบัญชีแท้</label><label class="check"><input v-model="form.whitelist" type="checkbox" /> เปิด whitelist</label></div></section></fieldset><p v-if="error" class="text-red-300 text-sm">{{error}}</p><button v-if="editable" class="button primary" :disabled="saving">{{saving?'กำลังบันทึก…':'บันทึกการตั้งค่า'}}</button></form><hr class="border-dark-700 my-8"/><section><h2 class="text-red-300 font-semibold">ลบเซิร์ฟเวอร์</h2><p class="text-dark-500 text-sm mt-1">ลบ container และไฟล์ทั้งหมด ไม่สามารถกู้คืนได้</p><button :disabled="!editable" class="button danger mt-4" @click="confirmDelete=true">ลบเซิร์ฟเวอร์</button></section><ConfirmDialog v-model="confirmDelete" danger title="ลบเซิร์ฟเวอร์?" message="ข้อมูลโลก, mods และไฟล์ทั้งหมดจะหายถาวร" confirm-text="ลบถาวร" @confirm="remove" /></div></template>
<script setup lang="ts">definePageMeta({layout:'server'});const route=useRoute(),router=useRouter(),store=useServersStore(),id=route.params.id as string;const server=computed(()=>store.servers.find(s=>s.id===id));const form=reactive<any>({}),saving=ref(false),error=ref(''),confirmDelete=ref(false);const editable=computed(()=>server.value?.status==='stopped');function assign(){if(server.value)Object.assign(form,server.value,{whitelist:!!server.value.whitelist,online_mode:!!server.value.online_mode})}async function save(){saving.value=true;error.value='';try{await store.updateServer(id,form)}catch(e:any){error.value=e?.data?.statusMessage||'บันทึกไม่สำเร็จ'}finally{saving.value=false}}async function remove(){try{await store.deleteServer(id);router.push('/')}catch(e:any){error.value=e?.data?.statusMessage||'ลบไม่สำเร็จ'}}onMounted(async()=>{await store.fetchServer(id);assign()})</script><style scoped>.panel{@apply bg-dark-900 border border-dark-700 rounded-2xl p-5}.panel h2{@apply text-white font-semibold}.field{@apply flex flex-col gap-1.5 text-sm text-dark-300}.field input,.field select{@apply rounded-lg bg-dark-800 border border-dark-600 px-3 py-2.5 text-white outline-none focus:border-mc-green}.check{@apply text-sm text-dark-300 flex items-center gap-2}.check input{@apply accent-green-400}.button{@apply px-4 py-2.5 rounded-xl font-medium text-sm transition-colors disabled:opacity-50}.primary{@apply bg-mc-green hover:bg-green-300 text-dark-950}.danger{@apply bg-red-700 hover:bg-red-600 text-white}</style>
